css:
#mgt-root-wrap { position: absolute; top: 0; left: 0; width: 100%; height: 100%; overflow: hidden; pointer-events: none; perspective: 1200px; }
#mgt-scene { position: absolute; transform: translate(-50%, -50%); display: flex; align-items: center; justify-content: center; pointer-events: auto; transform-style: preserve-3d; }
.mgt-card { position: absolute; border-radius: 16px; overflow: hidden; box-shadow: 0 20px 40px rgba(0,0,0,0.6); display: flex; align-items: center; justify-content: center; transform-origin: center center; border: 2px solid rgba(255,255,255,0.15); transition: none; }
.mgt-img { width: 100%; height: 100%; object-fit: cover; position: absolute; top: 0; left: 0; }
.mgt-ph { font-family: sans-serif; font-weight: 800; font-size: 14px; letter-spacing: 2px; color: rgba(255,255,255,0.5); text-transform: uppercase; }
#mgt-card-center { z-index: 30; }
#mgt-card-right { z-index: 20; }
#mgt-card-left { z-index: 10; }

render:
const p = ctx.params;
ctx.root.style.backgroundColor = p.bg_canvas_color;

const scene = ctx.root.querySelector('#mgt-scene');
const cardLeft = ctx.root.querySelector('#mgt-card-left');
const cardCenter = ctx.root.querySelector('#mgt-card-center');
const cardRight = ctx.root.querySelector('#mgt-card-right');

const imgL = ctx.image(p.img_left);
const imgC = ctx.image(p.img_center);
const imgR = ctx.image(p.img_right);

const cards = [
  { el: cardLeft, img: imgL },
  { el: cardCenter, img: imgC },
  { el: cardRight, img: imgR }
];

cards.forEach(c => {
  c.el.style.width = p.card_width + 'px';
  c.el.style.height = p.card_height + 'px';
  c.el.style.backgroundColor = p.bg_card_color;
  const ph = c.el.querySelector('.mgt-ph');
  if (c.img) {
    ph.style.display = 'none';
  } else {
    ph.style.display = 'block';
  }
});

cardCenter.style.borderColor = p.primary_color;
cardCenter.style.boxShadow = '0 0 30px ' + p.primary_color + '66, 0 25px 60px rgba(0,0,0,0.85)';

const posX = (p.pos_x / 100) * ctx.width;
const posY = (p.pos_y / 100) * ctx.height;

scene.style.left = posX + 'px';
scene.style.top = posY + 'px';

const prg = ctx.progress;

let inAnim = 0;
if (prg < 0.22) {
  const u = prg / 0.22;
  inAnim = 1 - Math.pow(1 - u, 4);
} else {
  inAnim = 1;
}

let outAnim = 0;
if (prg > 0.82) {
  const u = (prg - 0.82) / 0.18;
  outAnim = Math.pow(u, 3);
} else {
  outAnim = 0;
}

const speedVel = (1 - inAnim) * 1.0 + outAnim * 1.0;
const blurPx = speedVel * p.motion_blur_amount;

const gScale = p.global_scale;
const targetSep = p.overlap_offset;

// 1. TARJETA CENTRAL (Frente - Capa Superior: z-index 30)
// Sube desde abajo con un Tilt 3D elegante (Rotación X e Y) que se endereza al llegar
const cStartOffsetY = ctx.height * 0.45;
const cCurY = (1 - inAnim) * cStartOffsetY + outAnim * (cStartOffsetY * 0.6);
const cTiltX = (1 - inAnim) * p.center_tilt_amount - outAnim * (p.center_tilt_amount * 0.5);
const cTiltY = (1 - inAnim) * (-p.center_tilt_amount * 0.8);
const cScale = gScale * (0.75 + 0.25 * inAnim) * (1 - 0.15 * outAnim);

cardCenter.style.transform = 'translate3d(0px, ' + cCurY + 'px, 100px) scale(' + cScale + ') rotateX(' + cTiltX + 'deg) rotateY(' + cTiltY + 'deg)';
cardCenter.style.filter = blurPx > 0.5 ? 'blur(' + blurPx + 'px)' : 'none';
cardCenter.style.opacity = Math.min(1, inAnim * 2.5) * (1 - outAnim);

// 2. TARJETA DERECHA (Debajo del centro - Capa Media: z-index 20)
// Nace por la izquierda desfasada en plano Z profundo (-50px) para evitar colisión visual con el centro
const rStartX = -ctx.width * 0.45;
const rTargetX = targetSep;
const rCurX = (1 - inAnim) * rStartX + inAnim * rTargetX - outAnim * (rStartX * 0.7);
const rRotY = (1 - inAnim) * -18 + outAnim * 18;
const rScale = gScale * 0.92;

cardRight.style.transform = 'translate3d(' + rCurX + 'px, 0px, 20px) scale(' + rScale + ') rotateY(' + rRotY + 'deg)';
cardRight.style.filter = blurPx > 0.5 ? 'blur(' + blurPx * 1.1 + 'px)' : 'none';
cardRight.style.opacity = Math.min(1, inAnim * 2.5) * (1 - outAnim);

// 3. TARJETA IZQUIERDA (Debajo del todo - Capa Fondo: z-index 10)
// Nace por la derecha en el plano más profundo (-100px) deslizándose limpia por detrás
const lStartX = ctx.width * 0.45;
const lTargetX = -targetSep;
const lCurX = (1 - inAnim) * lStartX + inAnim * lTargetX + outAnim * (lStartX * 0.7);
const lRotY = (1 - inAnim) * 18 - outAnim * 18;
const lScale = gScale * 0.88;

cardLeft.style.transform = 'translate3d(' + lCurX + 'px, 0px, -40px) scale(' + lScale + ') rotateY(' + lRotY + 'deg)';
cardLeft.style.filter = blurPx > 0.5 ? 'blur(' + blurPx * 1.2 + 'px)' : 'none';
cardLeft.style.opacity = Math.min(1, inAnim * 2.5) * (1 - outAnim);
